  (1, 'solo_practice', 'Solo Practice', 'អនុវត្តតែម្នាក់', 'Practice at your own pace. Pick how many questions you want.', 'អនុវត្តតាមល្បឿនខ្លួនឯង។ គ្មានសម្ពាធម៉ោង។', 'Solo', NULL, NULL, FALSE, ARRAY['road-traffic', 'driving', 'technical', 'emergency', 'loading-people-goods', 'general-knowledge'], ARRAY['easy', 'medium', 'hard'], TRUE, '2026-04-05 20:49:42.907681', '2026-04-05 20:49:42.907681'),
  (2, 'solo_speed', 'Speed Quiz', 'ប្រណាំងល្បឿន', 'Race against the clock. Faster answers = more points.', 'ប្រណាំងជាមួយម៉ោង។ ចម្លើយលឿន = ពិន្ទុច្រើន។', 'Speed', NULL, 300, TRUE, ARRAY['road-traffic', 'driving', 'technical', 'emergency', 'loading-people-goods', 'general-knowledge'], ARRAY['easy', 'medium', 'hard'], TRUE, '2026-04-05 20:49:44.316029', '2026-04-05 20:49:44.316029'),
  (3, 'solo_exam', 'Exam Simulation', 'ការប្រឡងក្លែងធ្វើ', 'Simulate the real driving license exam. Mixed difficulty.', 'ក្លែងធ្វើការប្រឡងបណ្ណបើកបរពិតប្រាកដ។', 'Exam', NULL, 600, FALSE, ARRAY['road-traffic', 'driving', 'technical', 'emergency', 'loading-people-goods', 'general-knowledge'], ARRAY['easy', 'medium', 'hard'], TRUE, '2026-04-05 20:49:44.610991', '2026-04-05 20:49:44.610991'),
  (4, 'solo_category', 'Category Focus', 'ផ្តោតលើប្រភេទ', 'Deep-dive into one category at a time.', 'ស្វែងយល់ស៊ីជម្រៅក្នុងប្រភេទមួយ។', 'Focus', NULL, NULL, FALSE, ARRAY['road-traffic', 'driving', 'technical', 'emergency', 'loading-people-goods', 'general-knowledge'], ARRAY['easy', 'medium', 'hard'], TRUE, '2026-04-05 20:49:44.907146', '2026-04-05 20:49:44.907146'),
  (5, 'live_challenge', 'Live Challenge', 'ប្រកួតផ្ទាល់', 'Compete live with classmates. Teacher-hosted.', 'ប្រកួតផ្ទាល់ជាមួយមិត្តរួមថ្នាក់។ គ្រូជាម្ចាស់ផ្ទះ។', 'Live', NULL, NULL, TRUE, ARRAY['road-traffic', 'driving', 'technical', 'emergency', 'loading-people-goods', 'general-knowledge'], ARRAY['easy', 'medium', 'hard'], TRUE, '2026-04-05 20:49:45.200241', '2026-04-05 20:49:45.200241'),
